import{_ as n,o as e,c as t,ag as r}from"./chunks/framework.KxDd3USm.js";const h=JSON.parse('{"title":"12.1 计数与概率 ★★★","description":"","frontmatter":{},"headers":[],"relativePath":"12-数学与多媒体/01-计数与概率.md","filePath":"12-数学与多媒体/01-计数与概率.md"}'),p={name:"12-数学与多媒体/01-计数与概率.md"};function a(s,o,d,c,l,g){return e(),t("div",null,[...o[0]||(o[0]=[r('<h1 id="_12-1-计数与概率-★★★" tabindex="-1">12.1 计数与概率 ★★★ <a class="header-anchor" href="#_12-1-计数与概率-★★★" aria-label="Permalink to &quot;12.1 计数与概率 ★★★&quot;">​</a></h1><h3 id="_1-1-加法原理与乘法原理" tabindex="-1">1.1 加法原理与乘法原理 <a class="header-anchor" href="#_1-1-加法原理与乘法原理" aria-label="Permalink to &quot;1.1 加法原理与乘法原理&quot;">​</a></h3><p>计数题最先判断的不是排列还是组合，而是事情怎样完成。</p><ul><li><strong>分类完成，用加法</strong>：完成任务有若干条互斥路线，任选一条即可，总数相加；</li><li><strong>分步完成，用乘法</strong>：任务必须依次完成若干步，每步选择数相乘。</li></ul><p>例 1：从北京到上海可坐 4 趟火车或 3 个航班，任选一种方式，共 <code>4+3=7</code> 种。这是分类。</p><p>例 2：先从 4 件上衣中选 1 件，再从 3 条裤子中选 1 条，共 <code>4×3=12</code> 种。这是分步。</p><p><strong>反例前置</strong>：把“先选用户名，再选密码”算成用户名数+密码数是错的，因为一次完整登录凭据必须两步都完成，应使用乘法。</p><p><strong>应试动作</strong>：看到“或、任选一种路线”先想加法；看到“先……再……、同时具备”先想乘法。</p><h3 id="_1-2-排列-选出来以后还要排顺序" tabindex="-1">1.2 排列：选出来以后还要排顺序 <a class="header-anchor" href="#_1-2-排列-选出来以后还要排顺序" aria-label="Permalink to &quot;1.2 排列：选出来以后还要排顺序&quot;">​</a></h3><p>从 n 个不同元素中取 m 个并按顺序排列：</p><p><strong>A(n,m) = n×(n−1)×…×(n−m+1) = n!/(n−m)!</strong></p><p>其中 <code>n! = n×(n−1)×…×2×1</code>，并约定 <code>0!=1</code>。</p><p>例：从 6 人中选班长、学习委员、生活委员，职位不同，谁担任哪个职位会改变结果：</p><p><code>A(6,3)=6×5×4=120</code>。</p><p>手算口诀：<strong>有位置就排，依次递减乘</strong>。</p><h3 id="_1-3-组合-只选一组-不管组内顺序" tabindex="-1">1.3 组合：只选一组，不管组内顺序 <a class="header-anchor" href="#_1-3-组合-只选一组-不管组内顺序" aria-label="Permalink to &quot;1.3 组合：只选一组，不管组内顺序&quot;">​</a></h3><p>从 n 个不同元素中取 m 个组成一组：</p><p><strong>C(n,m) = n!/[m!(n−m)!] = A(n,m)/m!</strong></p><p>为何要除以 m!？同一组选出后，内部的 m! 种排列在组合里都算同一种。</p><p>例：从 6 人中选 3 人组成学习小组：</p><p><code>C(6,3)=(6×5×4)/(3×2×1)=120/6=20</code>。</p><p>反向验证：先排列有 120 种，但每个三人组被按 3!=6 种顺序重复计算，所以 <code>120/6=20</code>。</p><p>组合的对称性：<strong>C(n,m)=C(n,n−m)</strong>。从 10 人中选 8 人留下，等价于选 2 人不参加，因此 <code>C(10,8)=C(10,2)=45</code>。</p><p><strong>反例</strong>：“从 6 人中选 3 人参加会议”若算 <code>A(6,3)=120</code> 就错了。甲乙丙和丙乙甲是同一组，顺序不产生新结果。</p><p><strong>应试动作</strong>：给每个被选者假想贴职位标签——交换两人后算不算新结果？算新结果用排列，不算用组合。</p><h3 id="_1-4-可重复选择、重复元素排列与圆排列" tabindex="-1">1.4 可重复选择、重复元素排列与圆排列 <a class="header-anchor" href="#_1-4-可重复选择、重复元素排列与圆排列" aria-label="Permalink to &quot;1.4 可重复选择、重复元素排列与圆排列&quot;">​</a></h3><p><strong>每个位置可重复选择</strong>：若有 n 种字符，填 m 个位置，每个位置都可重复，共 <strong>n^m</strong> 种。</p><p>例：4 位数字验证码允许重复，每位 0–9 均可选，共 <code>10^4=10000</code> 种。若首位不能为 0，则第一位 9 种，其余各 10 种，共 <code>9×10^3=9000</code> 种。</p><p><strong>有重复元素的全排列</strong>：n 个元素中分别有 n1、n2…个相同元素：</p><p><strong>排列数 = n!/(n1!×n2!×…)</strong></p><p>例：<code>LEVEL</code> 有 5 个字母，L 重复 2 次、E 重复 2 次：</p><p><code>5!/(2!×2!)=120/4=30</code>。</p><p><strong>圆排列</strong>：n 个不同的人围成一圈，只把整体旋转视为相同，共 <strong>(n−1)!</strong> 种。固定一个人作为参照，其余 n−1 人线性排列即可。</p><p>例：4 人围圆桌坐（只旋转、不换相对座次算同一种），共 <code>(4−1)!=3!=6</code> 种；若站成一排则是 <code>4!=24</code> 种。两者差异正好是&quot;旋转的 n 倍&quot;：线形 <code>24 / 4 = 6</code> ✓。口诀：<strong>圆形是线形除以 n</strong>。</p><p><strong>应试动作</strong>：允许重复填位置用 n^m；相同元素被重复计算就除以各自阶乘；“围成一圈且旋转算同一种”用 <code>(n−1)!</code>。</p><h3 id="_1-5-容斥与抽屉原理" tabindex="-1">1.5 容斥与抽屉原理 <a class="header-anchor" href="#_1-5-容斥与抽屉原理" aria-label="Permalink to &quot;1.5 容斥与抽屉原理&quot;">​</a></h3><p>两个集合的容斥：</p><p><strong>|A∪B| = |A|+|B|−|A∩B|</strong></p><p>例：40 人中 25 人会 Java，18 人会 Python，10 人两者都会。至少会一种的有：</p><p><code>25+18−10=33</code> 人。两者都会的人被前两项算了两次，所以减回一次。</p><p>抽屉原理：把 n+1 个物品放进 n 个抽屉，至少一个抽屉有 2 个物品。推广形式：把 N 个物品放进 k 个抽屉，至少一个抽屉有 <strong>⌈N/k⌉</strong> 个物品。</p><p>例：13 个人按出生月份分到 12 个“月份抽屉”，至少 2 人同月出生。</p><p><strong>⌈⌉ 的代入算例</strong>（必背）：把 17 个苹果放进 5 个抽屉，<code>⌈17/5⌉=⌈3.4⌉=4</code>，所以至少有一个抽屉里有 4 个苹果。反向验证：若每个抽屉至多 3 个，5 个抽屉最多放 <code>5×3=15</code> 个，装不下 17 个 → 必有一个抽屉 ≥4 ✓。注意 ⌈⌉ 是<strong>向上取整</strong>（3.4 → 4），别取成 3。</p><p><strong>应试动作</strong>：看到“至少多少个相同类别”想抽屉原理（口诀：<strong>有余必进一</strong>）；看到“两类至少一个”先加后减交集。</p><hr><h2 id="第二节-概率基础-有利情况除以全部情况-★★" tabindex="-1">第二节 概率基础：有利情况除以全部情况 ★★ <a class="header-anchor" href="#第二节-概率基础-有利情况除以全部情况-★★" aria-label="Permalink to &quot;第二节 概率基础：有利情况除以全部情况 ★★&quot;">​</a></h2><p>在所有基本结果等可能时：</p><p><strong>P(A)=事件 A 的有利结果数 / 全部结果数</strong></p><p>例：从 5 个合格模块、3 个不合格模块中随机抽 2 个，恰好抽到 1 个不合格模块：</p><ul><li>全部选法：<code>C(8,2)=28</code>；</li><li>有利选法：从 3 个不合格中选 1 个、从 5 个合格中选 1 个，<code>C(3,1)×C(5,1)=15</code>；</li><li>概率：<code>15/28</code>。</li></ul><p>常用关系：</p><ul><li>对立事件：<code>P(非A)=1−P(A)</code>；</li><li>A、B 相互独立：<code>P(A∩B)=P(A)P(B)</code>；</li><li>一般加法：<code>P(A∪B)=P(A)+P(B)−P(A∩B)</code>。</li></ul><p>“至少一个成功”常用反面更快：</p><p><strong>P(至少一个成功)=1−P(全部失败)</strong></p><p>例：两个独立服务器单次成功率均为 0.9，至少一个成功的概率为 <code>1−0.1²=0.99</code>。</p><p><strong>反例</strong>：只有相互独立时才能直接把概率相乘。连续两次不放回抽球，第二次的概率会受第一次影响，不能机械写成同一个概率的平方。</p><p><strong>应试动作</strong>：题目有“等可能”才用有利/全部；遇到“至少一个”优先算“一个都没有”。</p><hr>',58)])])}const _=n(p,[["render",a]]);export{h as __pageData,_ as default};
